package com.chainauth.wallet;
import com.chainauth.auth.AuthService;import com.chainauth.user.*;import com.chainauth.wallet.dto.WalletVerifyRequest;import org.springframework.beans.factory.annotation.Value;import org.springframework.dao.DuplicateKeyException;import org.springframework.data.mongodb.core.MongoTemplate;import org.springframework.data.mongodb.core.FindAndModifyOptions;import org.springframework.data.mongodb.core.query.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.web.server.ResponseStatusException;import java.security.SecureRandom;import java.time.Instant;import java.util.*;
@Service public class WalletAuthService{
private static final SecureRandom RNG=new SecureRandom();private final WalletNonceRepository nonces;private final WalletRepository wallets;private final UserRepository users;private final MongoTemplate mongo;private final SiweMessageFactory factory;private final AuthService auth;private final Eip191SignatureVerifier signatureVerifier;private final long chainId;
public WalletAuthService(WalletNonceRepository n,WalletRepository w,UserRepository u,MongoTemplate m,SiweMessageFactory f,AuthService a,Eip191SignatureVerifier verifier,@Value("${app.blockchain.chain-id:31337}")long c){nonces=n;wallets=w;users=u;mongo=m;factory=f;auth=a;signatureVerifier=verifier;chainId=c;}
public WalletNonce issueNonce(String raw,long requested,String purpose,String userId){String address=normalize(raw);if(requested!=chainId)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unsupported wallet network");String p=purpose==null||purpose.isBlank()?"LOGIN":purpose.toUpperCase(Locale.ROOT);if(!p.equals("LOGIN")&&!p.equals("LINK"))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid nonce purpose");if(p.equals("LINK")&&(userId==null||userId.isBlank()))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Sign in before linking a wallet");if(p.equals("LOGIN")&&wallets.findByAddress(address).isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Wallet is not linked to a ChainAuth account");Instant i=Instant.now(),e=factory.expiry(i);byte[] b=new byte[16];RNG.nextBytes(b);WalletNonce n=new WalletNonce();n.setNonce(HexFormat.of().formatHex(b));n.setAddress(address);n.setChainId(requested);n.setPurpose(p);n.setUserId(userId);n.setIssuedAt(i);n.setExpiresAt(e);n.setMessage(factory.create(address,requested,n.getNonce(),i,e));n.setConsumed(false);return nonces.save(n);}
public Verified verify(WalletVerifyRequest r,String purpose,String userId){String address=normalize(r.address());WalletNonce n=nonces.findByMessageAndAddress(r.message(),address).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Wallet challenge is invalid or expired"));Instant now=Instant.now();if(n.isConsumed()||!n.getExpiresAt().isAfter(now)||!purpose.equals(n.getPurpose())||n.getChainId()!=chainId||(purpose.equals("LINK")&&!Objects.equals(n.getUserId(),userId)))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Wallet challenge is invalid or expired");if(!signatureVerifier.verify(n.getMessage(),r.signature(),address))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Wallet signature is invalid");Query q=new Query(Criteria.where("_id").is(n.getId()).and("consumed").is(false).and("expiresAt").gt(now));WalletNonce used=mongo.findAndModify(q,new Update().set("consumed",true),FindAndModifyOptions.options().returnNew(true),WalletNonce.class);if(used==null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Wallet challenge has already been used");
if(purpose.equals("LINK")){Wallet old=wallets.findByAddress(address).orElse(null);if(old!=null&&!old.getUserId().equals(userId))throw new ResponseStatusException(HttpStatus.CONFLICT,"Wallet already belongs to another account");if(old==null){Wallet w=new Wallet();w.setAddress(address);w.setUserId(userId);w.setChainId(n.getChainId());w.setLinkedAt(now);w.setLastUsedAt(now);try{wallets.save(w);}catch(DuplicateKeyException ex){throw new ResponseStatusException(HttpStatus.CONFLICT,"Wallet already linked");}}return new Verified(null,address);}
Wallet w=wallets.findByAddress(address).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Wallet is not linked"));User u=users.findById(w.getUserId()).filter(User::isEnabled).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Account unavailable"));w.setLastUsedAt(now);wallets.save(w);return new Verified(auth.loginWithWallet(u),address);}
public List<Wallet> list(String uid){return wallets.findAllByUserIdOrderByLinkedAtDesc(uid);}public void unlink(String id,String uid){Wallet w=wallets.findByIdAndUserId(id,uid).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Wallet not found"));User u=users.findById(uid).orElseThrow();if(u.getPasswordHash()==null&&wallets.findAllByUserIdOrderByLinkedAtDesc(uid).size()<=1)throw new ResponseStatusException(HttpStatus.CONFLICT,"Cannot unlink the only sign-in method");wallets.delete(w);}
private String normalize(String a){if(a==null||!a.matches("(?i)^0x[0-9a-f]{40}$"))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid Ethereum address");return"0x"+a.substring(2).toLowerCase(Locale.ROOT);}public record Verified(AuthService.Authenticated session,String address){}
}
